namespace App\Models;


use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\SoftDeletes;



/**
 * Generated Eloquent model for the watak table.
 */
class Character extends Model 
{
	
    
    use SoftDeletes;
    
    
    /**
     *
     * @var string
     */
    protected $table = 'watak';
    /**
     *
     * @var string
     */
    protected $primaryKey = 'id';
    /**
     *
     * @var array<int, string>
     */
    protected $fillable = [
        
        'nama_watak'
    
    ];
    
    


    public function complaints()
    {
        return $this->hasMany(Complaint::class, 'lk_watak', 'id');
    }
    public function complaintsLkWatakRadio()
    {
        return $this->hasMany(Complaint::class, 'lk_watak_radio', 'id');
    }	




}
